import React, { useEffect, useState } from 'react';
import api from '../../lib/api';

export default function AdminOrders(){
  const [orders, setOrders] = useState([]);
  const [meta, setMeta] = useState(null);
  const [loading, setLoading] = useState(false);

  async function load(page=1){
    setLoading(true);
    try{
      const r = await api.get(`/admin/orders?page=${page}`);
      const data = r.data;
      const list = Array.isArray(data) ? data : (Array.isArray(data?.data) ? data.data : []);
      setOrders(list);
      setMeta(data?.meta || null);
    }catch(err){
      console.error('Load orders failed:', err);
      const status = err.response?.status;
      if (status === 401 || status === 403) alert('Akses admin diperlukan.');
    }finally{
      setLoading(false);
    }
  }

  useEffect(()=>{ load(); },[]);

  return (
    <div style={{padding:20}}>
      <header style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>
        <strong>Admin</strong>
        <nav style={{display:'flex',gap:12}}>
          <a href="/admin/products">Products</a>
          <a href="/admin/orders">Orders</a>
          <a href="#" onClick={(e)=>{e.preventDefault(); localStorage.removeItem('hr_token'); localStorage.removeItem('hr_user'); window.location.href='/admin/login';}}>Logout</a>
        </nav>
      </header>
      <h2>Admin - Riwayat Pembelian</h2>
      {loading && <div>Loading...</div>}
      <table border="1" cellPadding={8} style={{width:'100%'}}>
        <thead>
          <tr>
            <th>ID</th>
            <th>Order</th>
            <th>Pembeli</th>
            <th>Status</th>
            <th>Total</th>
            <th>Items</th>
            <th>Waktu</th>
          </tr>
        </thead>
        <tbody>
          {orders.map(o => (
            <tr key={o.id}>
              <td>{o.id}</td>
              <td><a href={`/admin/orders/${o.id}`}>{o.order_number}</a></td>
              <td>{o.user ? `${o.user.name} (${o.user.email})` : '-'}</td>
              <td>{o.status}</td>
              <td>{o.total_amount}</td>
              <td>{Array.isArray(o.items) ? o.items.length : (typeof o.items === 'string' ? (()=>{ try { return JSON.parse(o.items).length } catch { return '-'; } })() : '-')}</td>
              <td>{o.created_at}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {meta && (
        <div style={{marginTop:12}}>
          <button disabled={!meta?.prev_page_url} onClick={()=> load((meta.current_page||1)-1)}>Prev</button>
          <span style={{margin:'0 8px'}}>Page {meta.current_page} / {meta.last_page}</span>
          <button disabled={!meta?.next_page_url} onClick={()=> load((meta.current_page||1)+1)}>Next</button>
        </div>
      )}
    </div>
  );
}
